function calculatePrice(order: Order) {
  if (order.isPromotional) {
    return applyPromo(order);
  } else if (order.customer.isPreferred) {
    return applyPreferredDiscount(order);
  } else if (order.total > 1000) {
    return applyBulkDiscount(order);
  } else {
    return standardPrice(order);
  }
}

/* Version A */
function computeDiscount(order: Order) {
  if (order.type === 'VIP') {
    return order.total * 0.2;
  } else if (order.type === 'Wholesale') {
    return order.total * 0.15 - 50;
  } else if (order.customer.age > 65) {
    return order.total * 0.1;
  }
  return 0;
}

/* Version B */
function computeDiscount(order: Order) {
  if (order.type === 'VIP') return vipDiscount(order);
  if (order.type === 'Wholesale') return wholesaleDiscount(order);
  if (order.customer.age > 65) return seniorDiscount(order);
  return 0;
}

function vipDiscount(o: Order) { return o.total * 0.2; }
function wholesaleDiscount(o: Order) { return o.total * 0.15 - 50; }
function seniorDiscount(o: Order) { return o.total * 0.1; }
